[CmdletBinding()]
param([string]$HostPath='')
$ErrorActionPreference='Stop'
if(!$HostPath){$HostPath=(Get-Process -Id $PID).Path}
$scriptPath=Join-Path $PSScriptRoot 'strategy-benchmark.ps1';$corpus=Join-Path $PSScriptRoot '..\..\source\registry\strategy-benchmark-corpus.json';$temp=Join-Path ([IO.Path]::GetTempPath()) ('sb-test-'+[guid]::NewGuid().ToString('N'));[void][IO.Directory]::CreateDirectory($temp);$script:passed=0;$script:failed=0
function Assert($condition,[string]$name){if($condition){$script:passed++}else{$script:failed++;throw "ASSERTION FAILED: $name"}}
function Invoke-Bench([string]$act,[string]$runs='', [string]$runPath='',[string]$extra='',[string]$corpusPath=$corpus){ $out=Join-Path $temp ('out-'+[guid]::NewGuid().ToString('N')+'.txt');$err=Join-Path $temp ('err-'+[guid]::NewGuid().ToString('N')+'.txt');$argLine='-NoProfile -File "'+$scriptPath+'" -Action "'+$act+'" -CorpusPath "'+$corpusPath+'" -Json';if($runs){$argLine+=' -RunsFile "'+$runs+'"'};if($runPath){$argLine+=' -RunFile "'+$runPath+'"'};if($extra){$argLine+=' '+$extra};$proc=Start-Process -FilePath $HostPath -ArgumentList $argLine -Wait -PassThru -NoNewWindow -RedirectStandardOutput $out -RedirectStandardError $err;return [pscustomobject]@{code=$proc.ExitCode;text=[IO.File]::ReadAllText($out,[Text.Encoding]::UTF8);error=[IO.File]::ReadAllText($err,[Text.Encoding]::UTF8)}}
function New-Run([string]$id,[string]$strategy='single',[string]$task='sb-01',[string]$source='unknown',$cost='UNKNOWN',$tokens='known',$done=$true,$ref=$true){$tv=if($tokens-eq'unknown'){'UNKNOWN'}else{10};$r=@{run_id=$id;task_id=$task;strategy=$strategy;started_at='2026-11-12T10:00:00Z';finished_at='2026-11-12T10:00:01Z';wall_ms=1000;tokens=@{input_tokens=$tv;output_tokens=5;cache_read_tokens=2;cache_write_tokens=1};cost_source=$source;cost=$cost;done=[bool]$done;verification=@{status=$(if($done){'verified_pass'}else{'failed'})};human_interventions=0;dispatches=1;model_attempts=1;retries=0;rep=1;order_index=1;seed=42;model='fixture-model';tier='T2';fixture_hash='sha256:fixture';cache_state='cold';strategy_params=@{escalations=0;rounds=0}};if($strategy-eq'critique'){$r.critic_model='critic-model';$r.critic_session='critic-session';$r.implementer_session='implementer-session'};if($source-eq'reported'){$r.cost=[double]$cost};if($ref){$r.kernel_ref='task/test';};$p=Join-Path $temp ('run-'+$id+'.json');[IO.File]::WriteAllText($p,($r|ConvertTo-Json -Depth 8 -Compress),[Text.UTF8Encoding]::new($false));return $p}
function Record([string]$path,[string]$runs){Invoke-Bench 'record-run' $runs $path '-AllowDesignOnly'}
try{
    $v=Invoke-Bench 'validate-corpus';Assert ($v.code-eq 0-and($v.text|ConvertFrom-Json).pilot_ready-eq$false) 'corpus validation exposes closed pilot'
    foreach($ceiling in @(0,-1,'UNKNOWN')){$copy=Join-Path $temp ('ceiling-'+[guid]::NewGuid().ToString('N')+'.json');$doc=Get-Content -LiteralPath $corpus -Raw|ConvertFrom-Json;$doc.pilot_ready=$true;$doc.pilot_cost_ceiling=$ceiling;[IO.File]::WriteAllText($copy,($doc|ConvertTo-Json -Depth 12),[Text.UTF8Encoding]::new($false));$check=Invoke-Bench 'validate-corpus' '' '' '' $copy;Assert ($check.code-ne 0-and(-not($check.text|ConvertFrom-Json).pilot_ready)) "pilot ceiling rejected: $ceiling"}
    $list=Invoke-Bench 'list-corpus';Assert ($list.code-eq 0-and($list.text|ConvertFrom-Json).tasks.Count-eq 12) 'list corpus includes metadata'
    $runs=Join-Path $temp 'runs.json';$r1=New-Run 'r1' 'single' 'sb-01' 'reported' 0.25;$r1obj=Get-Content -LiteralPath $r1 -Raw|ConvertFrom-Json;$r1obj|Add-Member -NotePropertyName design_only -NotePropertyValue $false -Force;[IO.File]::WriteAllText($r1,($r1obj|ConvertTo-Json -Depth 8 -Compress),[Text.UTF8Encoding]::new($false));$r2=New-Run 'r2' 'single' 'sb-07' 'unknown' 'UNKNOWN' 'unknown' $false;$r3=New-Run -id 'r3' -strategy 'cascade' -task 'sb-02' -source 'reported' -cost 0.50 -tokens 'known' -done $true -ref $false;$r3obj=Get-Content -LiteralPath $r3 -Raw|ConvertFrom-Json;$r3obj|Add-Member -NotePropertyName self_reported -NotePropertyValue $true -Force;$r3obj|Add-Member -NotePropertyName evidence_ref -NotePropertyValue 'evidence/demo' -Force;[IO.File]::WriteAllText($r3,($r3obj|ConvertTo-Json -Depth 8 -Compress),[Text.UTF8Encoding]::new($false));$r4=New-Run -id 'r4' -strategy 'critique' -task 'sb-03' -source 'reported' -cost 0.2;$r5=New-Run -id 'r5' -strategy 'cascade' -task 'sb-08' -source 'reported' -cost 0.1 -ref $false;$r5obj=Get-Content -LiteralPath $r5 -Raw|ConvertFrom-Json;$r5obj|Add-Member -NotePropertyName nested_metadata -NotePropertyValue ([pscustomobject]@{started_at='2026-11-12T10:00:00+05:30';finished_at='2026-11-12T10:00:01+05:30'}) -Force;[IO.File]::WriteAllText($r5,($r5obj|ConvertTo-Json -Depth 8 -Compress),[Text.UTF8Encoding]::new($false))
    $rec1=Record $r1 $runs;Assert ($rec1.code-eq 0-and($rec1.text|ConvertFrom-Json).design_only) 'valid append marked design-only';$savedRuns=[IO.File]::ReadAllText($runs,[Text.Encoding]::UTF8);Assert ($savedRuns -match '"design_only"\s*:\s*true') 'design_only false overridden to true';Assert ((Record $r2 $runs).code-eq 0) 'mixed unknown run append';$rec3=Record $r3 $runs;Assert ($rec3.code-eq 0-and($rec3.text|ConvertFrom-Json).self_reported) 'self_reported explicit on record';$r4obj=Get-Content -LiteralPath $r4 -Raw|ConvertFrom-Json;$r4obj.verification.status='failed';[IO.File]::WriteAllText($r4,($r4obj|ConvertTo-Json -Depth 8 -Compress),[Text.UTF8Encoding]::new($false));Assert ((Record $r4 $runs).code-eq 0) 'done with failed verification recorded but not verified';Assert ((Record $r5 $runs).code-eq 0) 'verified self-report-free candidate without reference';$savedRuns=[IO.File]::ReadAllText($runs,[Text.Encoding]::UTF8);Assert ($savedRuns.Contains('2026-11-12T10:00:00+05:30')) 'nested timestamp marker restored exactly'
    $before=[IO.File]::ReadAllText($runs,[Text.Encoding]::UTF8);$badCases=@(
        @{name='duplicate';run=$r1},
        @{name='timestamp';mutate={param($x)$x.finished_at='2026-11-11T00:00:00Z'}},
        @{name='negative';mutate={param($x)$x.wall_ms=-1}},
        @{name='wall not numeric';mutate={param($x)$x.wall_ms='fast'}},
        @{name='negative token';mutate={param($x)$x.tokens.input_tokens=-1}},
        @{name='fractional token';mutate={param($x)$x.tokens.output_tokens=1.5}},
        @{name='negative cost';mutate={param($x)$x.cost_source='reported';$x.cost=-0.1}},
        @{name='reported unknown';mutate={param($x)$x.cost_source='reported';$x.cost='UNKNOWN'}},
        @{name='unknown numeric';mutate={param($x)$x.cost_source='unknown';$x.cost=1}},
        @{name='done not bool';mutate={param($x)$x.done='yes'}},
        @{name='design_only not bool';expect='INVALID_BOOLEAN:design_only';mutate={param($x)$x|Add-Member -NotePropertyName design_only -NotePropertyValue 'yes' -Force}},
        @{name='missing critic evidence';expect='CRITIC_EVIDENCE_REQUIRED';strategy='critique';mutate={param($x)$x.PSObject.Properties.Remove('critic_session')}},
        @{name='critic same session';expect='CRITIC_SESSION_NOT_INDEPENDENT';strategy='critique';mutate={param($x)$x.critic_session=$x.implementer_session.ToUpperInvariant()}},
        @{name='blank critic model';expect='INVALID_CRITIC_MODEL';strategy='critique';mutate={param($x)$x.critic_model=' '}},
        @{name='blank critic session';expect='INVALID_CRITIC_SESSION';strategy='critique';mutate={param($x)$x.critic_session=' '}},
        @{name='seed string';mutate={param($x)$x.seed='42'}},
        @{name='negative order';mutate={param($x)$x.order_index=-1}},
        @{name='rep zero';mutate={param($x)$x.rep=0}},
        @{name='missing field';mutate={param($x)$x.PSObject.Properties.Remove('tokens')}},
        @{name='strategy not allowed';mutate={param($x)$x.strategy='invalid'}},
        @{name='noninteger count';mutate={param($x)$x.retries=1.5}}
    );$n=10;foreach($case in $badCases){if($case.name-eq'duplicate'){$bp=$r1}else{$caseStrategy='single';if($case.strategy){$caseStrategy=$case.strategy};$p=New-Run "bad$n" $caseStrategy;if($case.mutate){$obj=Get-Content -LiteralPath $p -Raw|ConvertFrom-Json;& $case.mutate $obj;$bp=Join-Path $temp "bad$n.json";[IO.File]::WriteAllText($bp,($obj|ConvertTo-Json -Depth 8 -Compress),[Text.UTF8Encoding]::new($false))}else{$bp=$p}};$x=Record $bp $runs;Assert ($x.code-ne 0) "reject $($case.name): $($x.error.Trim())";if($case.expect){Assert ($x.error.Contains($case.expect)) "error code $($case.expect) for $($case.name)"};Assert ([IO.File]::ReadAllText($runs,[Text.Encoding]::UTF8)-ceq$before) "file unchanged after $($case.name)";$n++}
    $dupeFile=Join-Path $temp 'duplicate-runs.json';$r1data=Get-Content -LiteralPath $r1 -Raw|ConvertFrom-Json;$dupData=@($r1data,$r1data)|ConvertTo-Json -Depth 8;[IO.File]::WriteAllText($dupeFile,$dupData,[Text.UTF8Encoding]::new($false));$dupeSummary=Invoke-Bench 'summarize' $dupeFile;Assert ($dupeSummary.code-ne 0-and$dupeSummary.error.Contains('DUPLICATE_RUN_ID')) 'summarize rejects duplicate run ids'
    $excluded=Invoke-Bench 'summarize' $runs;Assert (($excluded.text|ConvertFrom-Json).total_runs-eq 0-and($excluded.text|ConvertFrom-Json).excluded_design_only-eq 5) 'design-only excluded by default'
    $sum=Invoke-Bench 'summarize' $runs '' '-IncludeDesignOnly';$s=$sum.text|ConvertFrom-Json;Assert ($s.excluded_design_only-eq 0-and$s.included_design_only-eq 5-and$s.include_design_only) 'include design counts and flag';$single=@($s.strategies|Where-Object strategy -eq single)[0];$cascade=@($s.strategies|Where-Object strategy -eq cascade)[0];$critique=@($s.strategies|Where-Object strategy -eq critique)[0];Assert ($cascade.included_design_only-eq 2-and$cascade.excluded_design_only-eq 0) 'per-strategy included counts'
    $sumRepeat=Invoke-Bench 'summarize' $runs '' '-IncludeDesignOnly';Assert ($sum.text-ceq$sumRepeat.text) 'summarize byte deterministic'
    Assert ($single.tokens.input_tokens.total-ceq'UNKNOWN'-and$single.tokens.input_tokens.token_known_runs-eq 1) 'mixed token knownness surfaced';Assert ($single.tokens.output_tokens.total-eq 10-and$single.tokens.cache_write_tokens.total-eq 2) 'token totals include cache writes';Assert ($single.done-eq 1-and$single.cost_total-ceq'UNKNOWN'-and$single.observed_vs_unknown-ceq'unknown') 'done false and mixed cost handled';Assert ($cascade.done-eq 1-and$cascade.unverified_no_ref-eq 1-and$cascade.by_task[0].verified_done-eq 1-and$cascade.by_task[0].unverified_no_ref-eq 0) 'verification requires ref, independent of self_reported';Assert ($critique.done-eq 0-and$critique.by_task[0].verified_done-eq 0) 'failed verification is not verified';$empty=Join-Path $temp 'empty.json';[IO.File]::WriteAllText($empty,'[]',[Text.UTF8Encoding]::new($false));$emptySummary=(Invoke-Bench 'summarize' $empty).text|ConvertFrom-Json;$emptyCritique=@($emptySummary.strategies|Where-Object strategy -eq critique)[0];Assert ($null-eq$emptyCritique.success_rate-and$emptyCritique.cost_total-ceq'UNKNOWN'-and$emptyCritique.known_runs-eq 0-and$emptyCritique.observed_vs_unknown-ceq'no-runs'-and$emptyCritique.tokens.input_tokens.total-ceq'UNKNOWN') 'no runs semantics'
    $pilot=Join-Path $temp 'pilot.json';Assert ((Invoke-Bench 'record-run' $pilot $r1).error.Contains('PILOT_NOT_READY')) 'pilot gate refuses design corpus'
    $positiveCorpus=Join-Path $temp 'positive-ceiling.json';$pc=Get-Content -LiteralPath $corpus -Raw|ConvertFrom-Json;$pc.pilot_cost_ceiling=1.0;[IO.File]::WriteAllText($positiveCorpus,($pc|ConvertTo-Json -Depth 12),[Text.UTF8Encoding]::new($false));$positiveRuns=Join-Path $temp 'positive-pilot-runs.json';$blocked=Invoke-Bench 'record-run' $positiveRuns $r1 '' $positiveCorpus;Assert ($blocked.code-ne 0-and$blocked.error.Contains('PILOT_NOT_READY')) 'positive ceiling still blocks non-ready design pilot'
    $invalid=Join-Path $temp 'invalid-runs.json';[IO.File]::WriteAllText($invalid,'[{"run_id":"oops"}]',[Text.UTF8Encoding]::new($false));$badSum=Invoke-Bench 'summarize' $invalid;Assert ($badSum.code-ne 0-and$badSum.error.Contains('INVALID_RUNS_FILE')) 'summarize rejects malformed run file'
    $large=Join-Path $temp 'large.json';$many=@(1..5000|ForEach-Object{@{run_id="id$_"}});[IO.File]::WriteAllText($large,($many|ConvertTo-Json),[Text.UTF8Encoding]::new($false));$limit=Record $r1 $large;Assert ($limit.code-ne 0-and$limit.error.Contains('RUNS_LIMIT_REACHED')) 'run bound'
    Write-Output "RESULT: $script:passed passed; $script:failed failed"
}finally{Remove-Item -LiteralPath $temp -Recurse -Force -ErrorAction SilentlyContinue}
